 const ORDRE_FICHE=cases?['act','abon','mvt','reac','mait','pass','crit']:['act','abon','mvt','reac','pass','crit','mait'],rangT=t=>{const i=ORDRE_FICHE.indexOf(talentType(t)[0]);return i<0?ORDRE_FICHE.length:i};
