const ARMES_DEPART=[[['Épée courte',2]],[['Épée courte',1],['Bouclier',1]],[['Arc court',1],['Flèche',20]]];
const ARMURES_DEPART=[[['Armure de cuir',1]],[['Manteau',1]]],OBJETS_DEPART=[['Ration',10]],OR_DEPART='10d6';
