/* L'image qu'un joueur envoie par la table : assez légère pour y voyager. Safari ne sait pas écrire le WebP et rend un PNG bien
   plus lourd, qui dépassait la limite et ne partait pas : on réduit la taille jusqu'à passer, transparence gardée. */
const IMAGE_TABLE_MAX=60000;
async function imagePourTable(url){if(typeof url!=='string'||!url.startsWith('data:image/'))return null;if(url.length<=IMAGE_TABLE_MAX)return url;
 try{const im=new Image();im.src=url;await im.decode();
  for(const t of [192,160,128,96,72,64]){const k=Math.min(1,t/Math.max(im.naturalWidth,im.naturalHeight)),cv=document.createElement('canvas');
   cv.width=Math.max(1,Math.round(im.naturalWidth*k));cv.height=Math.max(1,Math.round(im.naturalHeight*k));cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);
   for(const [type,q] of [['image/webp',.85],['image/png',undefined]]){const d=cv.toDataURL(type,q);if(d.startsWith('data:'+type)&&d.length<=IMAGE_TABLE_MAX)return d}}}catch(e){}
 return null}
/* L'aventurier créé : sur la route, hors de la carte, avec ses 100 premiers XP ; chez un joueur, il devient le sien. La création
   s'achève sur le récapitulatif. Sa fiche ne garde que les points de compétence : le 1 de base, la classe et l'espèce s'y ajoutent
   au jeu, comme pour tout aventurier. */
function creerAventurier(){const c=creation;if(!c||ETAPES_CREATION.some(([k])=>etapeManque(k)))return;if(!peutCreerAventurier()){creationDialog.close();return}const e=especeCreation(c);
 const a=baseActor(true);Object.assign(a,{id:crypto.randomUUID(),name:majusculeInitiale(c.name.trim()),sexe:c.sexe,...(especeAvecSavoir(c)&&Number.isInteger(c[champSavoir(c)])?{[champSavoir(c)]:c[champSavoir(c)]}:{}),...(especeAvecAscendance(c)&&c.ascendance?{ascendance:c.ascendance}:{}),...(especeAvecHeritage(c)&&c.heritage?{heritage:c.heritage}:{}),...(Number(e.vitessePetit)>0&&c.socle==='small'?{socle:'small'}:{}),...(e.taille==='small'?{socle:'small'}:{}),race:e.nom,espece:e.id,role:c.role,vie:BASE_HEROS.vieMax,skills:c.skills.slice(),level:1,xp:XP_CREATION,horsCarte:true,lieuDomaine:'route',pointsCreation:{...c.caracs}});
 // L'équipement de départ au sac ; l'objet inhabituel, tiré ici, une seule fois.
 const kit=kitCreation(c);kit.forEach(([o,n])=>{for(let k=0;k<n;k++)a.inventaire.push(o.id)});
 const tiree=tirePieceDepart(c.role);if(tiree){a.forges=[tiree];a.inventaire.push(tiree.id)}
 // Et sa bourse : 10d6 pièces d'or.
 const or=Array.from({length:10},()=>1+Math.floor(Math.random()*6)).reduce((s,n)=>s+n,0);
 // Créé par un joueur à une table en ligne : il lui appartient, et le MJ le voit arriver.
 if(invitEnLigne()&&typeof monUid!=='undefined'&&monUid){a.joueur=monUid;a.joueurNom=pseudoJoueur()}
 // Son image : chez un joueur, elle part aussi par la table, pour que le MJ la reçoive.
 if(c.image){a.image=c.image;if(view!=='mj')a.imageJeton=c.imageTable||c.image}
 normalizeActor(a);ajouteOr(a,or);a.max=Math.max(1,pvMaximum(catalog.classes,a,catalog.talents,catalog.items));
 // Les armes, l'armure et les munitions du lot se portent d'emblée ; l'objet tiré attend au sac.
 kit.forEach(([o,n])=>{if(o.category==='weapon')for(let k=0;k<n;k++)toggleEquip(a,o);else if(o.category==='armor'||o.category==='ammo')toggleEquip(a,o)});
 a.max=Math.max(1,pvMaximum(catalog.classes,a,catalog.talents,catalog.items));a.hp=a.max;actors.push(a);syncForges();creation=null;creationDialog.close();
 const i=actors.indexOf(a);
 if(view!=='mj'){owner=i;selected=i;if(typeof enLigne!=='undefined'&&enLigne&&typeof prendreSiege==='function')prendreSiege(a)}
 render();if(view!=='mj'&&!(typeof enLigne!=='undefined'&&enLigne)&&$('owner'))$('owner').value=String(i);
 if(typeof renderHeroes==='function')renderHeroes();scheduleSave();if(typeof pousserBientot==='function')pousserBientot();renderAccueil();
 // L'objet tiré se montre aussitôt, comme à l'Armurerie : son carré et son nom, sa fiche au survol.
 if(tiree)annonceObjetDepart(objetDe(tiree.id))}
let objetDepartDialog=null;
function annonceObjetDepart(o){if(!o)return;
 objetDepartDialog??=dialog('objet-depart','Objet aléatoire','<div id="objet-depart-corps" class="objet-depart-corps"></div><div class="form-actions"><button type="button" class="primary" data-ok>OK</button></div>');
 objetDepartDialog.querySelector('[data-ok]').onclick=()=>objetDepartDialog.close();
 const carte=document.createElement('div');carte.className='cat-carte';
 const q=gearCarre(o,1,0);q.classList.remove('dispo');const coche=q.querySelector('.marque-porte');if(coche)coche.remove();q.removeAttribute('role');q.tabIndex=0;q.setAttribute('aria-label',o.name);
 surveille(q,()=>{const d=gearDetail(o,null,false);d.hidden=false;d.classList.add('large');ouvrirBulle(q,d,'bulle-gear')});
 const nom=document.createElement('span');nom.className='nom-carte';nom.textContent=o.name;carte.append(q,nom);
 $('objet-depart-corps').replaceChildren(carte);objetDepartDialog.showModal()}
$('accueil-creer').onclick=()=>openCreation();
function completerInventaire(a){if(!a)return;a.inventaire??=[];
 const besoin=new Map();[...(a.weapons||[]),...armuresDe(a),a.shieldId].filter(Boolean).forEach(id=>besoin.set(id,(besoin.get(id)||0)+1));
 besoin.forEach((n,id)=>{const ont=a.inventaire.filter(x=>x===id).length;for(let k=ont;k<n;k++)a.inventaire.push(id)})}
const objetDe=id=>(catalog.items||[]).find(o=>o&&o.id===id)||null;
/* Un adversaire porte toujours tout ce qu'il possède : il n'y a rien à équiper. Chaque arme est
   une variante, son bouton en combat ; aux autres emplacements, la pièce à la meilleure DEF, et
   autant qu'il y a de places ; le meilleur bouclier ; la première munition sert ses tirs. */
function equipementAdversaire(a,items){const l=[...new Set((a&&a.inventaire)||[])].map(id=>(items||[]).find(o=>o&&o.id===id)).filter(Boolean);
 const def=o=>Number(o.def)||0,meilleures=(liste,n)=>[...liste].sort((x,y)=>def(y)-def(x)).slice(0,n).map(o=>o.id);
 const armures=l.filter(o=>o.category==='armor');
 return {weapons:l.filter(o=>o.category==='weapon').map(o=>o.id),
  armures:EMPLACEMENTS.flatMap(([k,,n])=>meilleures(armures.filter(o=>emplacementDe(o)===k),n)),
  shieldId:meilleures(armures.filter(o=>emplacementDe(o)==='shield'),1)[0]||'',munitionId:(l.find(o=>o.category==='ammo')||{}).id||''}}
// Ce qu'il portait avant ce choix rejoint son inventaire, puis il porte tout.
function equipeAdversaire(a){if(!a||a.hero)return a;completerInventaire(a);Object.assign(a,equipementAdversaire(a,catalog.items));return a}
/* Le butin d'un adversaire : pour chaque pièce, la chance en pour cent qu'un exemplaire tombe
   quand il quitte la carte. Une pièce sans chance écrite tombe à 25 % ; zéro s'écrit, pour qu'elle
   ne tombe jamais. Une pièce qu'il ne possède plus n'en garde pas. */
