  const [t,v]=x.k.split('-'),nom=x.k==='or'?'Or':nomGemme(t,v,false),f=x.f>1?x.n+'d'+x.f:String(x.n),c=x.p!==undefined&&x.p<100?' · '+x.p+' %':'';
