   const couleurBonus=(x,f)=>{const p=paramsTalent(x)||{},carac=p.carac||'pv';if(carac==='comp')teinteCompetence(Math.max(0,Math.min(7,Number(p.comp)||0)),f);else f(carac==='orbe'?'138,99,201':STAT_TINTS[carac]||'150,150,150')};
