  // Le groupe des adversaires prend leurs talents, où qu'ils soient rangés ; les autres groupes ne les répètent pas.
  const liste=(catalog.talents||[]).filter(t=>!estBonus(t)&&!estVide(t)&&(famille===ADVERSAIRES&&avecAdv?estTalentAdversaire(t):talentFamily(t)===famille&&!(avecAdv&&estTalentAdversaire(t)))
   &&(!q||t.name.toLowerCase().includes(q)||(t.effects||'').toLowerCase().includes(q)))
   .sort((a,b)=>(a.level||1)-(b.level||1)||a.name.localeCompare(b.name,'fr'));
